css:
#tongsci1-3-3-2-catalase .ct-body { grid-template-columns: 1060px minmax(0, 1fr); }
#tongsci1-3-3-2-catalase .ct-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #c9cec7; }
#tongsci1-3-3-2-catalase .ct-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-2-catalase .ct-safe { position: absolute; right: 10px; top: 8px; margin: 0; z-index: 3; pointer-events: none; font: 700 14px/1.2 var(--f-body); color: #7a1f12; background: #fff7d6; border: 2px solid #c9a227; border-radius: 8px; padding: 4px 9px; }
#tongsci1-3-3-2-catalase .ct-safe::before { content: "⚠ "; }
#tongsci1-3-3-2-catalase .ct-panel { gap: 10px; }
#tongsci1-3-3-2-catalase .ct-out { margin: 0; font-size: 20px; line-height: 1.45; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 4.4em; flex: none; transition: background .2s; }
#tongsci1-3-3-2-catalase .ct-out b { color: var(--accent); }
#tongsci1-3-3-2-catalase .ct-out.bad { background: #ffe1dc; }
#tongsci1-3-3-2-catalase .ct-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 15px/1.25 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
#tongsci1-3-3-2-catalase .ct-tab thead th { font: 800 16px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 4px; }
#tongsci1-3-3-2-catalase .ct-tab thead th:nth-child(1) { width: 15%; }
#tongsci1-3-3-2-catalase .ct-tab thead th:nth-child(2) { width: 24%; }
#tongsci1-3-3-2-catalase .ct-tab thead th:nth-child(3) { width: 15%; }
#tongsci1-3-3-2-catalase .ct-tab thead th:nth-child(4) { width: 13%; }
#tongsci1-3-3-2-catalase .ct-tab tbody th { font: 700 15px/1.2 var(--f-body); text-align: center; border: 1.5px solid var(--rule, #c9ccd3); background: color-mix(in srgb, var(--ink) 4%, var(--paper-2)); }
#tongsci1-3-3-2-catalase .ct-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 3px 5px; height: 38px; text-align: center; }
#tongsci1-3-3-2-catalase .ct-tab td b { color: var(--ink-2); }
#tongsci1-3-3-2-catalase .ct-tab td b.on { color: var(--accent); }
#tongsci1-3-3-2-catalase .ct-tab td.why { text-align: left; font-size: 14px; }

